create or replace function public.coach_intelligence(p_competition text,p_team text) returns jsonb language sql stable security invoker set search_path=public as $$ with roster as(select distinct player_id,player_name from public.game_player_stats where competition=p_competition and team_name=p_team and verified=true),pm as(select r.player_id,r.player_name,public.player_memory_v2(r.player_id,p_competition)memory from roster r),ranked as(select *,case memory->>'flag' when 'ROLE_CHANGE' then 1 when 'TREND' then 2 when 'STABLE' then 3 else 4 end rank from pm),recent_games as(select g.id from public.games g where g.competition=p_competition and(g.home_team=p_team or g.away_team=p_team)order by g.game_date desc nulls last,g.id desc limit 5),quality as(select count(*)checks,count(*)filter(where d.status='PASS')passed,count(*)filter(where d.status='FAIL')failed from public.data_quality_checks d where d.game_id in(select id from recent_games))select jsonb_build_object('competition',p_competition,'team',p_team,'team_memory',public.team_memory(p_competition,p_team),'players',(select coalesce(jsonb_agg(jsonb_build_object('player_id',player_id,'player_name',player_name,'flag',memory->>'flag','confidence',memory->'confidence','summary',memory->'summary','last5',memory->'last5')order by rank,(memory->>'confidence')::numeric desc),'[]'::jsonb)from ranked),'evidence_claims',(select coalesce(jsonb_agg(jsonb_build_object('id',id,'claim',claim_text,'sample_games',sample_games,'sample_minutes',sample_minutes,'confidence',confidence,'games',evidence_game_ids,'video',video_evidence,'status',status)order by confidence desc nulls last),'[]'::jsonb)from public.intelligence_claims where competition=p_competition and subject_name=p_team and status='VERIFIED'),'data_quality',(select jsonb_build_object('checks',checks,'passed',passed,'failed',failed,'status',case when failed>0 then 'REVIEW' when checks=0 then 'INSUFFICIENT_DATA' else 'VERIFIED' end)from quality));$$;revoke all on function public.coach_intelligence(text,text) from public,anon;grant execute on function public.coach_intelligence(text,text) to authenticated;